    private sealed record InvoiceSnapshot(
        string Id,
        string CustomerName,
        decimal Amount,
        InvoiceStatus Status,
        DateTime CreatedAt,
        string? DecidedBy,
        DateTime? DecidedAt,
        string? DecisionNote,
        ApprovalDecision[] ApprovalHistory);

    private static InvoiceSnapshot Snapshot(Invoice invoice) =>
